//! Typed loaders for the parity documents generated by
//! `tests/fixtures/generate_optiq_parity_fixtures.py`.

use std::collections::BTreeMap;

use serde::Deserialize;

pub const ALLOCATION_PARITY_JSON: &str = include_str!("../fixtures/allocation_parity.json");
pub const TAXONOMY_PARITY_JSON: &str = include_str!("../fixtures/taxonomy_parity.json");
pub const STATIC_SCORER_PARITY_JSON: &str = include_str!("../fixtures/static_scorer_parity.json");
pub const ENCODER_PARITY_JSON: &str = include_str!("../fixtures/encoder_parity.json");

/// The Python checkpoint shape; `"NaN"` encodes a non-finite measurement.
#[derive(Debug, Deserialize)]
pub struct FixtureSensitivityEntry {
    pub layer_name: String,
    pub sensitivities: BTreeMap<String, serde_json::Value>,
    #[serde(rename = "param_count")]
    pub logical_parameter_count: u64,
}

/// The Python optimizer's keyword arguments, under their Python names on
/// disk and full names here.
#[derive(Debug, Deserialize)]
pub struct FixtureAllocationConstraints {
    #[serde(rename = "target_bpw")]
    pub target_bits_per_weight: f64,
    pub candidate_bits: Vec<u32>,
    #[serde(rename = "n_floor_per_block")]
    pub floor_components_per_block: usize,
    #[serde(rename = "max_low_bit_run")]
    pub maximum_low_bit_block_run: usize,
    #[serde(rename = "protect_first_last")]
    pub protect_boundary_blocks: bool,
}

#[derive(Debug, Deserialize)]
pub struct FixtureAllocationCase {
    pub constraints: FixtureAllocationConstraints,
    #[serde(rename = "achieved_bpw")]
    pub achieved_bits_per_weight: f64,
    #[serde(rename = "n_high_bits")]
    pub module_count_at_highest_width: usize,
    #[serde(rename = "n_low_bits")]
    pub module_count_at_lowest_width: usize,
    pub allocation: BTreeMap<String, u32>,
}

#[derive(Debug, Deserialize)]
pub struct AllocationParityFixture {
    pub optiq_version: String,
    pub sensitivity_table: Vec<FixtureSensitivityEntry>,
    pub cases: Vec<FixtureAllocationCase>,
}

#[derive(Debug, Deserialize)]
pub struct TaxonomyParityFixture {
    pub optiq_version: String,
    pub module_names: Vec<String>,
    pub block_index: BTreeMap<String, Option<usize>>,
    pub is_attention_component: BTreeMap<String, bool>,
    pub output_layers: Vec<String>,
    pub moe_protected_layers: Vec<String>,
    pub boundary_layers_n1: Vec<String>,
    pub shardwise_is_expert: BTreeMap<String, bool>,
    pub shardwise_is_router: BTreeMap<String, bool>,
}

#[derive(Debug, Deserialize)]
pub struct StaticScorerParityFixture {
    pub optiq_version: String,
    pub n_layers: usize,
    pub structural_priority: BTreeMap<String, f64>,
}

#[derive(Debug, Deserialize)]
pub struct EncoderParityCase {
    pub search_packed_words: Vec<u32>,
    pub search_scales: Vec<f32>,
    pub search_biases: Vec<f32>,
    pub stock_packed_words: Vec<u32>,
    pub stock_scales: Vec<f32>,
    pub stock_biases: Vec<f32>,
}

#[derive(Debug, Deserialize)]
pub struct KlDivergenceFixture {
    pub reference_logits: Vec<f32>,
    pub probe_logits: Vec<f32>,
    pub shape: Vec<usize>,
    pub kl_reference_vs_probe: f64,
}

#[derive(Debug, Deserialize)]
pub struct EncoderParityFixture {
    pub optiq_version: String,
    pub mlx_version: String,
    pub rows: usize,
    pub columns: usize,
    pub group_size: u32,
    pub weights_row_major: Vec<f32>,
    pub cases: BTreeMap<String, EncoderParityCase>,
    pub kl_divergence: KlDivergenceFixture,
}

pub fn allocation_parity() -> AllocationParityFixture {
    serde_json::from_str(ALLOCATION_PARITY_JSON)
        .expect("the allocation parity fixture should parse")
}

pub fn taxonomy_parity() -> TaxonomyParityFixture {
    serde_json::from_str(TAXONOMY_PARITY_JSON).expect("the taxonomy parity fixture should parse")
}

pub fn static_scorer_parity() -> StaticScorerParityFixture {
    serde_json::from_str(STATIC_SCORER_PARITY_JSON)
        .expect("the static scorer parity fixture should parse")
}

pub fn encoder_parity() -> EncoderParityFixture {
    serde_json::from_str(ENCODER_PARITY_JSON).expect("the encoder parity fixture should parse")
}

/// Translates a fixture KL value, decoding the `"NaN"` marker.
pub fn fixture_kl_value(value: &serde_json::Value) -> f64 {
    match value {
        serde_json::Value::String(marker) if marker == "NaN" => f64::NAN,
        serde_json::Value::Number(number) => number.as_f64().expect("fixture numbers fit f64"),
        other => panic!("unexpected fixture KL value {other}"),
    }
}

#[test]
fn should_parse_every_parity_fixture_and_record_the_pinned_optiq_version() {
    assert_eq!(allocation_parity().optiq_version, "0.6.5");
    assert_eq!(taxonomy_parity().optiq_version, "0.6.5");
    assert_eq!(static_scorer_parity().optiq_version, "0.6.5");
    let encoder = encoder_parity();
    assert_eq!(encoder.optiq_version, "0.6.5");
    assert!(!encoder.mlx_version.is_empty());
    assert_eq!(
        encoder.weights_row_major.len(),
        encoder.rows * encoder.columns
    );
    let group_count = encoder.rows * encoder.columns / encoder.group_size as usize;
    for case in encoder.cases.values() {
        assert_eq!(case.search_scales.len(), group_count);
        assert_eq!(case.search_biases.len(), group_count);
        assert_eq!(case.stock_scales.len(), group_count);
        assert_eq!(case.stock_biases.len(), group_count);
    }
}
